<?php require __DIR__.'/_init.php';require_login();$q=db()->prepare("SELECT COUNT(*) total,SUM(status IN ('submitted','in_review','in_progress')) open_count,SUM(status='completed') done FROM service_requests WHERE user_id=?");$q->execute([$_SESSION['user']['id']]);$stats=$q->fetch();$q=db()->prepare('SELECT tracking_id,title,status,created_at FROM service_requests WHERE user_id=? ORDER BY created_at DESC LIMIT 5');$q->execute([$_SESSION['user']['id']]);$recent=$q->fetchAll();page_start('Dashboard');?><div class="eyebrow">STUDENT SPACE</div><h1>Hello, <?=e(explode(' ',$_SESSION['user']['full_name'])[0])?>.</h1><p>Here’s your campus support at a glance.</p><div class="stats"><article><small>ALL REQUESTS</small><strong><?=$stats['total']??0?></strong></article><article><small>IN PROGRESS</small><strong><?=$stats['open_count']??0?></strong></article><article><small>COMPLETED</small><strong><?=$stats['done']??0?></strong></article></div><div class="row"><h2>Recent requests</h2><a href="/requests.php">View all →</a></div><?php if(!$recent):?><div class="empty"><h3>Your support desk is ready</h3><p>Submit a request and track it here.</p><a class="button" href="/new-request.php">New request →</a></div><?php else:?><div class="table-wrap"><table><tr><th>Tracking ID</th><th>Request</th><th>Status</th><th>Date</th></tr><?php foreach($recent as $r):?><tr><td><?=e($r['tracking_id'])?></td><td><?=e($r['title'])?></td><td><span class="pill"><?=e(str_replace('_',' ',$r['status']))?></span></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table></div><?php endif;?><p><a class="button" href="/new-request.php">Submit a service request</a></p><?php page_end();?>
